sqlReaderQuery.value:
@coalesce(
    if(
      not(empty(item().customQuery)),
      replace(
        item().customQuery,
        '{{LoadDate}}',
        formatDateTime(
          coalesce(
            pipeline().parameters.LoadDate,
            formatDateTime(
              convertTimeZone(utcNow(),'UTC','AUS Eastern Standard Time'),
              'yyyy-MM-dd'
            )
          ),
          'yyyy-MM-dd'
        )
      ),
      null
    ),
    if(
      equals(item().partitionOption,'DynamicRange'),
      concat(
        'SELECT * FROM ', item().sourceSchema, '.', item().sourceTable,
        ' WHERE ?DfDynamicRangePartitionCondition',
        if(
          equals(item().loadType,'Incremental'),
          concat(
            ' AND ', item().highWaterColumn, ' >= ''',
            formatDateTime(
              coalesce(
                pipeline().parameters.LoadDate,
                formatDateTime(
                  convertTimeZone(utcNow(),'UTC','AUS Eastern Standard Time'),
                  'yyyy-MM-dd'
                )
              ),
              'yyyy-MM-dd'
            ),
            ''' AND ', item().highWaterColumn, ' < DATEADD(day,1,''',
            formatDateTime(
              coalesce(
                pipeline().parameters.LoadDate,
                formatDateTime(
                  convertTimeZone(utcNow(),'UTC','AUS Eastern Standard Time'),
                  'yyyy-MM-dd'
                )
              ),
              'yyyy-MM-dd'
            ),
            ''')'
          ),
          ''
        )
      ),
      if(
        equals(item().loadType,'Incremental'),
        concat(
          'SELECT * FROM ', item().sourceSchema, '.', item().sourceTable,
          ' WHERE ', item().highWaterColumn, ' >= ''',
          formatDateTime(
            coalesce(
              pipeline().parameters.LoadDate,
              formatDateTime(
                convertTimeZone(utcNow(),'UTC','AUS Eastern Standard Time'),
                'yyyy-MM-dd'
              )
            ),
            'yyyy-MM-dd'
          ),
          ''' AND ', item().highWaterColumn, ' < DATEADD(day,1,''',
          formatDateTime(
            coalesce(
              pipeline().parameters.LoadDate,
              formatDateTime(
                convertTimeZone(utcNow(),'UTC','AUS Eastern Standard Time'),
                'yyyy-MM-dd'
              )
            ),
            'yyyy-MM-dd'
          ),
          ''')'
        ),
        concat('SELECT * FROM ', item().sourceSchema, '.', item().sourceTable)
      )
    )
  )

preCopyScript.value:
@{concat(
    'BEGIN ',
      'ALTER SESSION SET QUERY_TAG = ''ADF:', pipeline().RunId, ':', item().targetSchema, '.', item().targetTable, ''';',
      if(
        equals(toLower(coalesce(item().rawWriteMode, 'Append')), 'fullreplace'),
        concat('TRUNCATE TABLE ', item().targetSchema, '.', item().targetTable, ';'),
        ''
      ),
    'END;'
  )}
